import{_ as e,o as t,c as n,a6 as i}from"./chunks/framework.DycQjAfF.js";const g=JSON.parse('{"title":"SOP Permintaan Kode Material Baru","description":"Cara mengajukan kode material baru untuk stock item dan non-stock item, sesuai standar cataloguing Warehouse BPI.","frontmatter":{"title":"SOP Permintaan Kode Material Baru","description":"Cara mengajukan kode material baru untuk stock item dan non-stock item, sesuai standar cataloguing Warehouse BPI.","status":"ditinjau","dasar":"Instruksi Kerja Permintaan Kode Material Baru Gudang Teknik","nomor_dokumen":null,"versi":0.3,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-20T00:00:00.000Z","kategori":"SOP","sumber":["ik-gudang-teknik"],"kata_kunci":["SOP","kode material baru","nomor material","cataloguing","material master list","stock item","non stock item","PR","purchase request","memo","admin cataloguing","foreman control material master","head of division","internal control","level stock","ROP","duplikasi kode"]},"headers":[],"relativePath":"sop/kode-material-baru.md","filePath":"sop/kode-material-baru.md"}'),r={name:"sop/kode-material-baru.md"};function o(s,a,u,d,l,m){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="sop-permintaan-kode-material-baru" tabindex="-1">SOP Permintaan Kode Material Baru <a class="header-anchor" href="#sop-permintaan-kode-material-baru" aria-label="Permalink to &quot;SOP Permintaan Kode Material Baru&quot;">​</a></h1><p class="lead">Dipakai ketika sebuah departemen membutuhkan barang yang belum punya kode di sistem ERP/WMS. Isinya diringkas dari Instruksi Kerja Permintaan Kode Material Baru Gudang Teknik.</p><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Menjadi pedoman Gudang Teknik dalam membuat atau menambah kode material baru ke Material Master List dan database sistem, dengan deskripsi yang jelas, spesifikasi yang tepat, dan <strong>tanpa kode ganda</strong>. Kode dibuat sesuai <a href="/WareHouse/divisi/kode-barang">standar cataloguing Warehouse BPI</a>.</p><h2 id="berlaku-untuk" tabindex="-1">Berlaku untuk <a class="header-anchor" href="#berlaku-untuk" aria-label="Permalink to &quot;Berlaku untuk&quot;">​</a></h2><p>Pembuatan kode material baru untuk <strong>stock item</strong> maupun <strong>non-stock item</strong>. Berlaku untuk semua departemen (user) yang membutuhkan barang baru yang belum punya kode di sistem.</p><h2 id="peran" tabindex="-1">Peran <a class="header-anchor" href="#peran" aria-label="Permalink to &quot;Peran&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Peran</th><th>Tanggung jawab</th></tr></thead><tbody><tr><td data-label="Peran"><strong>Supervisor Gudang</strong></td><td data-label="Tanggung jawab">Mengawasi kepatuhan terhadap instruksi kerja.</td></tr><tr><td data-label="Peran"><strong>Foreman Control Material Master &amp; Cataloguing</strong></td><td data-label="Tanggung jawab">Mengontrol material master dan level stok sesuai perhitungan yang ditetapkan, serta menganalisanya sesuai kegiatan produksi yang sedang berjalan (<em>job order</em>).</td></tr><tr><td data-label="Peran"><strong>Admin Cataloguing</strong></td><td data-label="Tanggung jawab">Memverifikasi data, mengecek apakah sudah ada kode serupa, lalu menginput kode baru ke sistem.</td></tr><tr><td data-label="Peran"><strong>Admin Pembuat PR Stock Item</strong></td><td data-label="Tanggung jawab">Membuat dan menerbitkan PR (<em>purchase request</em>) untuk material stock item.</td></tr><tr><td data-label="Peran"><strong>User (pemohon)</strong></td><td data-label="Tanggung jawab">Melengkapi data spesifikasi barang, mengajukan permintaan, dan menerbitkan PR untuk material non-stock item.</td></tr></tbody></table><h2 id="sebelum-mengajukan" tabindex="-1">Sebelum mengajukan <a class="header-anchor" href="#sebelum-mengajukan" aria-label="Permalink to &quot;Sebelum mengajukan&quot;">​</a></h2><ol><li><strong>Pastikan materialnya memang belum ada</strong> di sistem WMS. Ini mencegah satu barang punya dua kode.</li><li><strong>Tentukan jenisnya</strong>: dijadikan stock item di gudang, atau cukup non-stock item. Pertimbangkan seberapa sering material itu dipakai. Lihat <a href="/WareHouse/divisi/manajemen-inventory#stock-item-dan-non-stock-item">Manajemen Stok</a>.</li></ol><h2 id="untuk-stock-item" tabindex="-1">Untuk stock item <a class="header-anchor" href="#untuk-stock-item" aria-label="Permalink to &quot;Untuk stock item&quot;">​</a></h2><ol><li><strong>User membuat memo pengajuan</strong> kode material baru untuk dijadikan stock item. Memo disetujui dan ditandatangani Head of Division terkait, dan perlu persetujuan Section Head of Internal Control.</li><li><strong>Isi memo menjelaskan secara rinci:</strong><ul><li>tujuan material dijadikan stock item,</li><li>deskripsi detail dan spesifikasi lengkap,</li><li>analisa pemakaian <strong>3 tahun ke belakang</strong> dan perkiraan pemakaian per bulan.</li></ul></li><li><strong>Kode dibuat</strong> setelah memo disetujui Supervisor atau Section Head of Warehouse, sesuai standar cataloguing. Sekaligus ditentukan level stoknya (stok maksimum, stok minimum, jumlah pesan, lead time, dan ROP) serta lokasi penyimpanannya.</li><li><strong>Kode diinput ke ERP</strong>, lalu Admin Pembuat PR langsung menerbitkan PR untuk material tersebut.</li></ol><h2 id="untuk-non-stock-item" tabindex="-1">Untuk non-stock item <a class="header-anchor" href="#untuk-non-stock-item" aria-label="Permalink to &quot;Untuk non-stock item&quot;">​</a></h2><ol><li><p><strong>User mengisi format &quot;Pengajuan Permintaan dan Monitoring Kode Material Baru&quot;</strong>, dengan data:</p><ul><li>nama material,</li><li>jenis atau bahan,</li><li>spesifikasi,</li><li>fungsi atau sifat,</li><li>dimensi,</li><li>jumlah dan satuan (UoM).</li></ul><p>Permintaan dikirim ke Warehouse lewat email yang diketahui atasan terkait, atau lewat sistem aplikasi perusahaan.</p></li><li><p><strong>Kalau datanya belum lengkap</strong>, Admin Cataloguing berhak mengembalikan pengajuan ke user untuk diperbaiki. Lampirkan foto barang atau brosur teknis jika perlu, supaya deskripsinya jelas.</p></li><li><p><strong>Kode dibuat</strong> setelah permintaan disetujui Indirect Material Supervisor Warehouse, sesuai standar cataloguing.</p></li><li><p><strong>Admin Cataloguing memberi tahu user</strong> kode yang baru lewat email atau sistem aplikasi perusahaan. Setelah itu, user membuat dan menerbitkan PR.</p></li></ol><h2 id="ringkasan-perbedaan" tabindex="-1">Ringkasan perbedaan <a class="header-anchor" href="#ringkasan-perbedaan" aria-label="Permalink to &quot;Ringkasan perbedaan&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th></th><th>Stock item</th><th>Non-stock item</th></tr></thead><tbody><tr><td>Bentuk pengajuan</td><td data-label="Stock item">Memo</td><td data-label="Non-stock item">Format pengajuan lewat email atau sistem</td></tr><tr><td>Persetujuan pengajuan</td><td data-label="Stock item">Head of Division dan Section Head of Internal Control</td><td data-label="Non-stock item">Atasan terkait mengetahui</td></tr><tr><td>Persetujuan di Warehouse</td><td data-label="Stock item">Supervisor atau Section Head of Warehouse</td><td data-label="Non-stock item">Indirect Material Supervisor Warehouse</td></tr><tr><td>Data tambahan</td><td data-label="Stock item">Analisa pemakaian 3 tahun dan perkiraan pemakaian per bulan</td><td data-label="Non-stock item">Foto atau brosur teknis jika perlu</td></tr><tr><td>Level stok dan lokasi</td><td data-label="Stock item">Ditentukan saat kode dibuat</td><td data-label="Non-stock item">Tidak disimpan sebagai stok</td></tr><tr><td>Yang menerbitkan PR</td><td data-label="Stock item">Admin Pembuat PR Stock Item</td><td data-label="Non-stock item">User (pemohon)</td></tr></tbody></table><h2 id="baca-juga" tabindex="-1">Baca juga <a class="header-anchor" href="#baca-juga" aria-label="Permalink to &quot;Baca juga&quot;">​</a></h2><ul><li><a href="/WareHouse/divisi/kode-barang">Kode Barang: struktur nomor material dan cara menulis deskripsi</a></li><li><a href="/WareHouse/divisi/manajemen-inventory">Manajemen Stok</a></li></ul>',18)])])}const b=e(r,[["render",o]]);export{g as __pageData,b as default};
